  Widget _speakerTile(BuildContext context,LudoController c,Map<String,dynamic> speaker,int index,{bool large=false}){
    final id='${speaker['userId']}';final mine=id==c.userId;final hot=speaker['micEnabled']==true;final host=speaker['userId']==c.activeVoiceRoom?['hostId'];final canKick=c.activeVoiceRoom?['hostId']==c.userId&&!mine;final size=large?86.0:52.0;
    return GestureDetector(onTap:()=>_giftTo(context,c,speaker),onLongPress:canKick?()=>c.kickMicSeat(id):null,child:Column(mainAxisSize:MainAxisSize.min,children:[Stack(alignment:Alignment.center,clipBehavior:Clip.none,children:[_SpeakerPulse(size:size,hot:hot,avatar:'${speaker['avatar']??'🙂'}',accent:host?_roomGold:_roomPink),Positioned(left:-5,top:-4,child:_seatBadge(index)),if(host)Positioned(right:-8,top:-6,child:const Icon(Icons.workspace_premium,color:_roomGold,size:19)),if(canKick)Positioned(right:-8,bottom:-4,child:IconButton(onPressed:()=>c.kickMicSeat(id),padding:EdgeInsets.zero,constraints:const BoxConstraints.tightFor(width:25,height:25),icon:const Icon(Icons.remove_circle,color:Colors.redAccent,size:20)))]),const SizedBox(height:5),Text(mine?'YOU':'${speaker['name']??'Player'}',maxLines:1,overflow:TextOverflow.ellipsis,style:TextStyle(fontWeight:FontWeight.bold,fontSize:large?12:9,color:host?_roomGold:Colors.white70)),if(!hot)const Text('MUTED',style:TextStyle(color:Colors.white30,fontSize:7,fontWeight:FontWeight.bold))]));
