class _GiftConfettiPainter extends CustomPainter{_GiftConfettiPainter(this.progress,this.seed);final double progress;final int seed;@override void paint(Canvas canvas,Size size){final colors=[_roomPink,_roomGold,const Color(0xFF45B7FF),Colors.white];for(var i=0;i<38;i++){final random=Random(seed+i*19);final x=random.nextDouble()*size.width;final y=((progress*size.height*1.35+i*61+random.nextDouble()*size.height*.4)%(size.height+50))-25;canvas.save();canvas.translate(x,y);canvas.rotate(progress*5+i*.72);canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromCenter(center:Offset.zero,width:4+random.nextDouble()*5,height:8+random.nextDouble()*11),const Radius.circular(2)),Paint()..color=colors[i%colors.length].withOpacity((.85-progress*.15).clamp(0,1).toDouble()));canvas.restore();}}@override bool shouldRepaint(covariant _GiftConfettiPainter old)=>old.progress!=progress||old.seed!=seed;}
